{
  "root": "main_stack",
  "state": {},
  "elements": {
    "main_stack": {
      "type": "Stack",
      "props": {
        "direction": "vertical",
        "gap": "md"
      },
      "children": [
        "header_section",
        "intro_paragraph",
        "curriculum_section",
        "quick_actions_section",
        "sources_section"
      ]
    },
    "header_section": {
      "type": "Stack",
      "props": {
        "direction": "horizontal",
        "gap": "sm",
        "align": "center"
      },
      "children": [
        "header_icon",
        "main_title"
      ]
    },
    "header_icon": {
      "type": "Icon",
      "props": {
        "name": "https://cdn.jsdelivr.net/npm/bootstrap-icons@1.11.3/icons/book.svg"
      },
      "children": []
    },
    "main_title": {
      "type": "Text",
      "props": {
        "text": "CS201: Data Structures and Algorithms Overview",
        "variant": "h2"
      },
      "children": []
    },
    "intro_paragraph": {
      "type": "Text",
      "props": {
        "text": "An introductory Data Structures and Algorithms (DSA) course (often designated CS201 or similar) is a fundamental component of any computer science undergraduate curriculum. It focuses on teaching efficient ways to store and organize data, and how to design algorithms to process that data effectively. This course builds a critical foundation for more advanced topics in software engineering, artificial intelligence, and systems design."
      },
      "children": []
    },
    "curriculum_section": {
      "type": "Stack",
      "props": {
        "direction": "vertical",
        "gap": "md"
      },
      "children": [
        "curriculum_header_stack",
        "curriculum_intro_paragraph",
        "prerequisites_title",
        "prerequisites_list",
        "core_topics_title",
        "core_topics_list",
        "learning_outcomes_title",
        "learning_outcomes_list"
      ]
    },
    "curriculum_header_stack": {
      "type": "Stack",
      "props": {
        "direction": "horizontal",
        "gap": "sm",
        "align": "center"
      },
      "children": [
        "curriculum_icon",
        "curriculum_title"
      ]
    },
    "curriculum_icon": {
      "type": "Icon",
      "props": {
        "name": "https://cdn.jsdelivr.net/npm/bootstrap-icons@1.11.3/icons/diagram-3.svg"
      },
      "children": []
    },
    "curriculum_title": {
      "type": "Text",
      "props": {
        "text": "Curriculum and Foundational Concepts",
        "variant": "h3"
      },
      "children": []
    },
    "curriculum_intro_paragraph": {
      "type": "Text",
      "props": {
        "text": "This course typically covers both theoretical concepts and practical implementation, often using a language like Java, C++, or Python."
      },
      "children": []
    },
    "prerequisites_title": {
      "type": "Text",
      "props": {
        "text": "Prerequisites:",
        "variant": "h3"
      },
      "children": []
    },
    "prerequisites_list": {
      "type": "Stack",
      "props": {
        "direction": "vertical",
        "gap": "sm",
        "paddingHorizontal": 16
      },
      "children": [
        "prereq_1",
        "prereq_2"
      ]
    },
    "prereq_1": {
      "type": "Text",
      "props": {
        "text": "• Introduction to Programming: Solid understanding of basic programming constructs (variables, data types, control flow, functions/methods, object-oriented programming fundamentals)."
      },
      "children": []
    },
    "prereq_2": {
      "type": "Text",
      "props": {
        "text": "• Discrete Mathematics: Familiarity with basic set theory, logic, proof techniques, and mathematical induction can be beneficial but is sometimes covered briefly within the DSA course itself."
      },
      "children": []
    },
    "core_topics_title": {
      "type": "Text",
      "props": {
        "text": "Core Topics Covered:",
        "variant": "h3"
      },
      "children": []
    },
    "core_topics_list": {
      "type": "Stack",
      "props": {
        "direction": "vertical",
        "gap": "sm",
        "paddingHorizontal": 16
      },
      "children": [
        "topic_intro_algorithms",
        "topic_basic_ds",
        "topic_trees",
        "topic_graphs",
        "topic_sorting",
        "topic_hashing",
        "topic_advanced"
      ]
    },
    "topic_intro_algorithms": {
      "type": "Stack",
      "props": {
        "direction": "vertical",
        "gap": "xs"
      },
      "children": [
        "text_intro_algorithms",
        "text_intro_algorithms_sub1",
        "text_intro_algorithms_sub2"
      ]
    },
    "text_intro_algorithms": {
      "type": "Text",
      "props": {
        "text": "• Introduction to Algorithms:"
      },
      "children": []
    },
    "text_intro_algorithms_sub1": {
      "type": "Text",
      "props": {
        "text": "  - Definition of an algorithm, properties, and design approaches."
      },
      "children": []
    },
    "text_intro_algorithms_sub2": {
      "type": "Text",
      "props": {
        "text": "  - Time and Space Complexity Analysis: Big O notation (O, Ω, Θ), best/average/worst-case analysis, recurrence relations."
      },
      "children": []
    },
    "topic_basic_ds": {
      "type": "Stack",
      "props": {
        "direction": "vertical",
        "gap": "xs"
      },
      "children": [
        "text_basic_ds",
        "text_basic_ds_sub1",
        "text_basic_ds_sub2",
        "text_basic_ds_sub3",
        "text_basic_ds_sub4"
      ]
    },
    "text_basic_ds": {
      "type": "Text",
      "props": {
        "text": "• Basic Data Structures:"
      },
      "children": []
    },
    "text_basic_ds_sub1": {
      "type": "Text",
      "props": {
        "text": "  - Arrays: Static and dynamic arrays, multi-dimensional arrays."
      },
      "children": []
    },
    "text_basic_ds_sub2": {
      "type": "Text",
      "props": {
        "text": "  - Linked Lists: Singly, doubly, and circularly linked lists; operations (insertion, deletion, traversal)."
      },
      "children": []
    },
    "text_basic_ds_sub3": {
      "type": "Text",
      "props": {
        "text": "  - Stacks: LIFO principle, array-based and linked-list based implementations, applications (function calls, expression evaluation)."
      },
      "children": []
    },
    "text_basic_ds_sub4": {
      "type": "Text",
      "props": {
        "text": "  - Queues: FIFO principle, array-based and linked-list based implementations, applications (scheduling, breadth-first search)."
      },
      "children": []
    },
    "topic_trees": {
      "type": "Stack",
      "props": {
        "direction": "vertical",
        "gap": "xs"
      },
      "children": [
        "text_trees",
        "text_trees_sub1",
        "text_trees_sub2",
        "text_trees_sub3"
      ]
    },
    "text_trees": {
      "type": "Text",
      "props": {
        "text": "• Trees:"
      },
      "children": []
    },
    "text_trees_sub1": {
      "type": "Text",
      "props": {
        "text": "  - General Trees: Terminology (root, node, child, parent, leaf), tree traversals (in-order, pre-order, post-order)."
      },
      "children": []
    },
    "text_trees_sub2": {
      "type": "Text",
      "props": {
        "text": "  - Binary Trees: Properties, binary search trees (BSTs), AVL trees, Red-Black trees (often an introduction to balanced trees)."
      },
      "children": []
    },
    "text_trees_sub3": {
      "type": "Text",
      "props": {
        "text": "  - Heaps: Max-heap, min-heap, heap sort, priority queues."
      },
      "children": []
    },
    "topic_graphs": {
      "type": "Stack",
      "props": {
        "direction": "vertical",
        "gap": "xs"
      },
      "children": [
        "text_graphs",
        "text_graphs_sub1",
        "text_graphs_sub2",
        "text_graphs_sub3",
        "text_graphs_sub4"
      ]
    },
    "text_graphs": {
      "type": "Text",
      "props": {
        "text": "• Graphs:"
      },
      "children": []
    },
    "text_graphs_sub1": {
      "type": "Text",
      "props": {
        "text": "  - Representations: Adjacency matrix, adjacency list."
      },
      "children": []
    },
    "text_graphs_sub2": {
      "type": "Text",
      "props": {
        "text": "  - Graph traversals: Breadth-First Search (BFS), Depth-First Search (DFS)."
      },
      "children": []
    },
    "text_graphs_sub3": {
      "type": "Text",
      "props": {
        "text": "  - Minimum Spanning Trees: Prim's algorithm, Kruskal's algorithm."
      },
      "children": []
    },
    "text_graphs_sub4": {
      "type": "Text",
      "props": {
        "text": "  - Shortest Path Algorithms: Dijkstra's algorithm (single source), Bellman-Ford (for negative weights)."
      },
      "children": []
    },
    "topic_sorting": {
      "type": "Stack",
      "props": {
        "direction": "vertical",
        "gap": "xs"
      },
      "children": [
        "text_sorting",
        "text_sorting_sub1",
        "text_sorting_sub2",
        "text_sorting_sub3"
      ]
    },
    "text_sorting": {
      "type": "Text",
      "props": {
        "text": "• Sorting Algorithms:"
      },
      "children": []
    },
    "text_sorting_sub1": {
      "type": "Text",
      "props": {
        "text": "  - Comparison sorts: Bubble, Selection, Insertion, Merge, Quick, Heap Sort."
      },
      "children": []
    },
    "text_sorting_sub2": {
      "type": "Text",
      "props": {
        "text": "  - Non-comparison sorts: Counting, Radix, Bucket Sort."
      },
      "children": []
    },
    "text_sorting_sub3": {
      "type": "Text",
      "props": {
        "text": "  - Stability, in-place sorting concepts."
      },
      "children": []
    },
    "topic_hashing": {
      "type": "Stack",
      "props": {
        "direction": "vertical",
        "gap": "xs"
      },
      "children": [
        "text_hashing",
        "text_hashing_sub1",
        "text_hashing_sub2"
      ]
    },
    "text_hashing": {
      "type": "Text",
      "props": {
        "text": "• Hashing:"
      },
      "children": []
    },
    "text_hashing_sub1": {
      "type": "Text",
      "props": {
        "text": "  - Hash functions, collision resolution techniques (chaining, open addressing)."
      },
      "children": []
    },
    "text_hashing_sub2": {
      "type": "Text",
      "props": {
        "text": "  - Hash tables and their applications."
      },
      "children": []
    },
    "topic_advanced": {
      "type": "Stack",
      "props": {
        "direction": "vertical",
        "gap": "xs"
      },
      "children": [
        "text_advanced",
        "text_advanced_sub1",
        "text_advanced_sub2",
        "text_advanced_sub3"
      ]
    },
    "text_advanced": {
      "type": "Text",
      "props": {
        "text": "• Introduction to Advanced Topics (often briefly covered):"
      },
      "children": []
    },
    "text_advanced_sub1": {
      "type": "Text",
      "props": {
        "text": "  - Dynamic Programming."
      },
      "children": []
    },
    "text_advanced_sub2": {
      "type": "Text",
      "props": {
        "text": "  - Greedy Algorithms."
      },
      "children": []
    },
    "text_advanced_sub3": {
      "type": "Text",
      "props": {
        "text": "  - Backtracking and Divide and Conquer paradigms."
      },
      "children": []
    },
    "learning_outcomes_title": {
      "type": "Text",
      "props": {
        "text": "Learning Outcomes:",
        "variant": "h3"
      },
      "children": []
    },
    "learning_outcomes_list": {
      "type": "Stack",
      "props": {
        "direction": "vertical",
        "gap": "sm",
        "paddingHorizontal": 16
      },
      "children": [
        "outcome_1",
        "outcome_2",
        "outcome_3",
        "outcome_4"
      ]
    },
    "outcome_1": {
      "type": "Text",
      "props": {
        "text": "• Analyze the time and space complexity of algorithms using Big O notation."
      },
      "children": []
    },
    "outcome_2": {
      "type": "Text",
      "props": {
        "text": "• Choose appropriate data structures and algorithms for various computational problems."
      },
      "children": []
    },
    "outcome_3": {
      "type": "Text",
      "props": {
        "text": "• Implement fundamental data structures (e.g., linked lists, trees, graphs) and algorithms (e.g., sorting, searching, graph traversals)."
      },
      "children": []
    },
    "outcome_4": {
      "type": "Text",
      "props": {
        "text": "• Apply problem-solving techniques using data structures and algorithms to real-world scenarios."
      },
      "children": []
    },
    "quick_actions_section": {
      "type": "Stack",
      "props": {
        "direction": "vertical",
        "gap": "md"
      },
      "children": [
        "quick_actions_title",
        "quick_actions_buttons"
      ]
    },
    "quick_actions_title": {
      "type": "Text",
      "props": {
        "text": "Quick Actions",
        "variant": "h3"
      },
      "children": []
    },
    "quick_actions_buttons": {
      "type": "Stack",
      "props": {
        "direction": "horizontal",
        "gap": "md",
        "wrap": "wrap"
      },
      "children": [
        "syllabus_button",
        "resources_button"
      ]
    },
    "syllabus_button": {
      "type": "Button",
      "props": {
        "label": "Explore Course Syllabus"
      },
      "on": {
        "press": {
          "action": "openUrl",
          "params": {
            "url": "https://example.edu/cs201/syllabus"
          }
        }
      },
      "children": []
    },
    "resources_button": {
      "type": "Button",
      "props": {
        "label": "Find Online Resources"
      },
      "on": {
        "press": {
          "action": "openUrl",
          "params": {
            "url": "https://www.geeksforgeeks.org/data-structures/"
          }
        }
      },
      "children": []
    },
    "sources_section": {
      "type": "Stack",
      "props": {
        "direction": "vertical",
        "gap": "md"
      },
      "children": [
        "sources_title",
        "sources_list"
      ]
    },
    "sources_title": {
      "type": "Text",
      "props": {
        "text": "References",
        "variant": "h3"
      },
      "children": []
    },
    "sources_list": {
      "type": "Stack",
      "props": {
        "direction": "vertical",
        "gap": "sm",
        "paddingHorizontal": 16
      },
      "children": [
        "source_1",
        "source_2"
      ]
    },
    "source_1": {
      "type": "Text",
      "props": {
        "text": "• Cormen, T. H., Leiserson, C. E., Rivest, R. L., & Stein, C. (2009). Introduction to Algorithms (3rd ed.). MIT Press."
      },
      "children": []
    },
    "source_2": {
      "type": "Text",
      "props": {
        "text": "• Goodrich, M. T., Tamassia, R., & Goldwasser, M. H. (2014). Data Structures and Algorithms in Java (6th ed.). Wiley."
      },
      "children": []
    }
  }
}
